import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, getExamDurations, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '', // This will be populated with the selected franchiseId
    examName: '',     // User input for exam name
    date: '',         // Default to current date
    durationInMinutes: '', // Duration is now a dropdown
    status: 'inprogress', // Default status
  });
  const [franchiseList, setFranchiseList] = useState([]); // Added state for list of franchises
  const [durationList, setDurationList] = useState([]); // Added state for exam durations
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [userName, setUserName] = useState(''); // Added state for user name

  const validExamNames = [
    'ServiceNow: CAD',
    'ServiceNow: CSA',
    'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION',
    'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer',
    'Salesforce administrators',
    'Google cloud',
    'Mulesoft',
    'Fusion'
  ];

  const validStatuses = ['complete', 'absent', 'inprogress']; // Status should match backend enums

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [franchiseData, durationData] = await Promise.all([
          getAssociatedFranchises(),
          getExamDurations()
        ]);
        console.log('Fetched Data:', franchiseData, durationData); // Log the response data

        // Flatten if data[0] is an array
        const flattenedFranchises = Array.isArray(franchiseData[0]) ? franchiseData[0] : franchiseData;
        const flattenedDurations = Array.isArray(durationData[0]) ? durationData[0] : durationData;

        if (flattenedFranchises && flattenedFranchises.length > 0) {
          setFranchiseList(flattenedFranchises); // Set the franchise list
          setExamData((prevData) => ({
            ...prevData,
            franchiseId: flattenedFranchises[0]?._id || '',
          })); // Set default franchiseId
        } else {
          setError('No associated franchises found for the user.');
        }

        if (flattenedDurations && flattenedDurations.length > 0) {
          setDurationList(flattenedDurations); // Set the duration list
        } else {
          setError('No exam durations available.');
        }

        const currentDate = new Date().toISOString().split('T')[0]; // Get current date in YYYY-MM-DD format
        setExamData((prevData) => ({
          ...prevData,
          date: currentDate,
        }));
      } catch (error) {
        setError('Failed to fetch the associated franchises or durations.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  const handleUserNameChange = (e) => {
    setUserName(e.target.value); // Update the userName state
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    if (!examData.examName || !validExamNames.includes(examData.examName)) {
      setError('Please select a valid exam name.');
      return;
    }

    if (!examData.status || !validStatuses.includes(examData.status.toLowerCase())) {
      setError('Please select a valid status.');
      return;
    }

    if (!examData.date) {
      setError('Please provide the exam date.');
      return;
    }

    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      setError('Invalid date format.');
      return;
    }

    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) {
      setError('Please select a valid exam duration.');
      return;
    }

    setLoading(true);
    try {
      const formattedDate = examDate.toISOString().split('T')[0]; // Format the date to YYYY-MM-DD

      // Adjust the payload to match backend structure
      const payload = {
        franchiseId: examData.franchiseId, // The franchiseId is still needed, as createUserExamData expects it
        examData: [
          {
            name: userName,  // Map 'userName' to 'name' in payload
            examName: examData.examName,
            date: formattedDate,
            durationInMinutes: examData.durationInMinutes,
            status: examData.status.toLowerCase(),  // Ensure status is in lowercase
          },
        ],
      };

      console.log('Payload being sent:', payload); // Log the payload before the API call
      await createUserExamData(payload); // Ensure this matches the API contract
      setSuccess('Exam data created successfully!');
      setExamData({
        franchiseId: examData.franchiseId,
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress', // Default to 'inprogress'
      });
      setError(null);
      setUserName(''); // Clear the user name field after submission

      // Reload the page after successful submission
      window.location.reload();
    } catch (error) {
      console.error('Error creating exam data:', error);
      setError(error.response?.data?.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        <div style={styles.formGroup}>
          <label htmlFor="franchiseId" style={styles.label}>Select Franchise</label>
          <select
            name="franchiseId"
            value={examData.franchiseId}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select a franchise</option>
            {franchiseList.length > 0 ? (
              franchiseList.map((franchise) => (
                <option key={franchise._id} value={franchise._id}>
                  {franchise.name}
                </option>
              ))
            ) : (
              <option value="" disabled>No franchises available</option>
            )}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="userName" style={styles.label}>Name</label>
          <input
            type="text"
            name="userName"
            value={userName}
            onChange={handleUserNameChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          <select
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select an exam</option>
            {validExamNames.map((exam, index) => (
              <option key={index} value={exam}>
                {exam}
              </option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="durationInMinutes" style={styles.label}>Duration (Minutes)</label>
          <select
            name="durationInMinutes"
            value={examData.durationInMinutes}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select duration</option>
            {durationList.map((duration, index) => (
              <option key={index} value={duration.value}>
                {duration.label}
              </option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="status" style={styles.label}>Status</label>
          <select
            name="status"
            value={examData.status}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="inprogress">In Progress</option>
            <option value="complete">Complete</option>
            <option value="absent">Absent</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
    display: 'flex',
